CREATE TABLE albums (id TEXT PRIMARY KEY, title TEXT NOT NULL, album_month TEXT, event_id TEXT REFERENCES events(id) ON DELETE SET NULL, diary_id TEXT REFERENCES diaries(id) ON DELETE SET NULL, trip_id TEXT REFERENCES trips(id) ON DELETE SET NULL, location_id TEXT REFERENCES locations(id) ON DELETE SET NULL);
CREATE TABLE album_photos (album_id TEXT NOT NULL REFERENCES albums(id) ON DELETE CASCADE, photo_id TEXT NOT NULL, PRIMARY KEY(album_id,photo_id));
CREATE INDEX idx_album_photos_photo ON album_photos(photo_id);
ALTER TABLE events ADD COLUMN cover_photo_id TEXT;
