INSERT OR IGNORE INTO album_photos SELECT 'legacy-december-2025', id FROM photos WHERE substr(COALESCE((SELECT taken FROM photo_details WHERE photo_id=photos.id),uploaded_at),1,7)='2025-12';
-- Ngày đã chỉnh trong D1 có ưu tiên hơn ngày từ manifest.
DELETE FROM album_photos WHERE album_id='legacy-december-2025' AND photo_id IN (SELECT photo_id FROM photo_details WHERE taken IS NOT NULL AND substr(taken,1,7)<>'2025-12');
INSERT OR IGNORE INTO album_photos SELECT 'legacy-december-2025', photo_id FROM photo_details WHERE substr(taken,1,7)='2025-12' AND photo_id NOT IN (SELECT id FROM deleted_photos);
